-- Fresh installations only. Back up an existing database and compare its schema first.
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, email TEXT UNIQUE, role TEXT NOT NULL DEFAULT 'viewer', status TEXT NOT NULL DEFAULT 'invited', pass_hash TEXT, salt TEXT, iters INTEGER NOT NULL DEFAULT 100000, pass_ver INTEGER NOT NULL DEFAULT 0, kind TEXT NOT NULL DEFAULT 'staff', public INTEGER NOT NULL DEFAULT 0, last_login TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE UNIQUE INDEX IF NOT EXISTS single_owner ON users(role) WHERE role='owner';
CREATE TABLE IF NOT EXISTS login_attempts (ip TEXT NOT NULL, ts INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS login_ip_ts ON login_attempts(ip,ts);
CREATE INDEX IF NOT EXISTS login_ts ON login_attempts(ts);
CREATE TABLE IF NOT EXISTS reset_tokens (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, token_hash TEXT NOT NULL UNIQUE, exp INTEGER NOT NULL, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS agents (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'active', can_read INTEGER NOT NULL DEFAULT 1, can_propose INTEGER NOT NULL DEFAULT 1, owner_id INTEGER, site_id INTEGER, created_at TEXT NOT NULL DEFAULT (datetime('now')), last_seen_at TEXT);
CREATE INDEX IF NOT EXISTS agents_owner ON agents(owner_id);
CREATE TABLE IF NOT EXISTS pages (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', content_json TEXT NOT NULL DEFAULT '[]', updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS versions (id INTEGER PRIMARY KEY AUTOINCREMENT, page_id INTEGER NOT NULL, content_json TEXT NOT NULL, source TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS versions_page ON versions(page_id,id);
CREATE TABLE IF NOT EXISTS sites (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, entry TEXT NOT NULL DEFAULT 'index.html');
CREATE TABLE IF NOT EXISTS site_files (site_id INTEGER NOT NULL, path TEXT NOT NULL, r2_key TEXT NOT NULL, size INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(site_id,path));
CREATE TABLE IF NOT EXISTS proposals (id INTEGER PRIMARY KEY AUTOINCREMENT, agent_id INTEGER NOT NULL, page_id INTEGER, site_id INTEGER, kind TEXT NOT NULL DEFAULT 'page', title TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', new_content_json TEXT NOT NULL DEFAULT '[]', sealed INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'waiting', owner_id INTEGER, owner_comment TEXT, decided_at TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS proposals_owner_status ON proposals(owner_id,status,id);
CREATE INDEX IF NOT EXISTS proposals_agent_status ON proposals(agent_id,status);
CREATE TABLE IF NOT EXISTS upload_files (proposal_id INTEGER NOT NULL, path TEXT NOT NULL, size INTEGER NOT NULL DEFAULT 0, deleted INTEGER NOT NULL DEFAULT 0, object_key TEXT, object_etag TEXT, PRIMARY KEY(proposal_id,path));
CREATE TABLE IF NOT EXISTS site_backups (proposal_id INTEGER NOT NULL, site_id INTEGER NOT NULL, path TEXT NOT NULL, r2_key TEXT, existed INTEGER NOT NULL DEFAULT 0, restored INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(proposal_id,path));
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value_json TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY AUTOINCREMENT, actor TEXT NOT NULL, action TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS cf_connections (id INTEGER PRIMARY KEY AUTOINCREMENT, label TEXT NOT NULL UNIQUE, account_id TEXT NOT NULL, token_enc TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS remote_sites (id INTEGER PRIMARY KEY AUTOINCREMENT, label TEXT NOT NULL, kind TEXT NOT NULL, url TEXT NOT NULL, username TEXT, client_id TEXT, secret_enc TEXT NOT NULL, ref TEXT, status TEXT NOT NULL DEFAULT 'pending', owner_id INTEGER, registry_id INTEGER);
CREATE UNIQUE INDEX IF NOT EXISTS remote_owner_label ON remote_sites(COALESCE(owner_id,0),label);
CREATE TABLE IF NOT EXISTS github_sites (id INTEGER PRIMARY KEY AUTOINCREMENT, label TEXT NOT NULL, repo TEXT NOT NULL, branch TEXT NOT NULL DEFAULT 'main', dir TEXT NOT NULL DEFAULT '', secret_enc TEXT NOT NULL, owner_id INTEGER, registry_id INTEGER);
CREATE UNIQUE INDEX IF NOT EXISTS github_owner_label ON github_sites(COALESCE(owner_id,0),label);
CREATE TABLE IF NOT EXISTS ai_accounts (id INTEGER PRIMARY KEY AUTOINCREMENT, label TEXT NOT NULL, provider TEXT NOT NULL, base_url TEXT, model TEXT NOT NULL, key_enc TEXT NOT NULL, owner_id INTEGER);
CREATE UNIQUE INDEX IF NOT EXISTS ai_owner_label ON ai_accounts(COALESCE(owner_id,0),label);
CREATE TABLE IF NOT EXISTS registry_sites (id INTEGER PRIMARY KEY AUTOINCREMENT, owner_id INTEGER NOT NULL, domain TEXT NOT NULL, name TEXT NOT NULL, token TEXT NOT NULL, verified_at TEXT, UNIQUE(owner_id,domain));
CREATE INDEX IF NOT EXISTS registry_domain ON registry_sites(domain,verified_at);
CREATE TABLE IF NOT EXISTS works (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL, site_id INTEGER, kind TEXT NOT NULL, author_type TEXT NOT NULL, author_label TEXT NOT NULL, approver TEXT NOT NULL, content_hash TEXT NOT NULL, prev_hash TEXT NOT NULL, hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS works_site_date ON works(site_id,created_at);
CREATE INDEX IF NOT EXISTS works_user_date ON works(user_id,created_at);

CREATE TABLE IF NOT EXISTS proposal_reviews (proposal_id INTEGER NOT NULL, user_id INTEGER NOT NULL, candidate_hash TEXT NOT NULL, baseline_hash TEXT NOT NULL, snapshot_hash TEXT NOT NULL, manifest_json TEXT NOT NULL, expires_at INTEGER NOT NULL, previewed_at INTEGER, PRIMARY KEY(proposal_id,user_id));
CREATE TABLE IF NOT EXISTS operation_locks (lock_key TEXT PRIMARY KEY, token TEXT NOT NULL, acquired_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS releases (id TEXT PRIMARY KEY, proposal_id INTEGER NOT NULL, owner_id INTEGER, user_id INTEGER NOT NULL, title TEXT NOT NULL, kind TEXT NOT NULL, target_key TEXT NOT NULL, candidate_hash TEXT NOT NULL, snapshot_hash TEXT NOT NULL, before_json TEXT NOT NULL, after_hash TEXT, status TEXT NOT NULL, result_json TEXT, error TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), finished_at TEXT);
CREATE INDEX IF NOT EXISTS releases_owner_date ON releases(owner_id,created_at);
CREATE INDEX IF NOT EXISTS releases_proposal ON releases(proposal_id);
